{
  "id": "test-workflow-001",
  "query": "index=wineventlog EventCode=4625 sourcetype=WinEventLog:Security | stats count by src_ip | where count > 10",
  "parsed_json": {
    "base_search": {
      "index": "wineventlog",
      "criteria": [
        {
          "field": "EventCode",
          "operator": "=",
          "value": "4625"
        },
        {
          "field": "sourcetype",
          "operator": "=",
          "value": "WinEventLog:Security"
        }
      ]
    },
    "pipeline": [
      {
        "command": "stats",
        "arguments": {
          "function": "count",
          "by": [
            "src_ip"
          ]
        }
      },
      {
        "command": "where",
        "arguments": {
          "condition": "count > 10"
        }
      }
    ],
    "time_window": {
      "type": "sliding",
      "value": 1,
      "unit": "hours"
    }
  },
  "fields": {
